insert into public.courses
  (slug, name_en, name_ta, duration, price, summary_en, summary_ta, syllabus_en, syllabus_ta, who_for_en, who_for_ta, certificate, placement, emi, sort_order, published)
values
('basic-beautician','Basic Beautician','அடிப்படை அழகுக்கலை','3 months',null,
 'Our Basic Beautician course is the proven launchpad for women entering the beauty industry quickly and confidently. Across three intensive months you master threading, waxing, bleach, basic facials, manicure, pedicure, head massage and salon hygiene. Every day blends short theory with long hands-on practice on live models, so by graduation you can comfortably handle walk-in clients. Batches stay capped at ten students, you keep your starter kit, and the course closes with a government-recognised certificate plus internship and placement guidance — the fastest, safest way to start earning from beauty work in Chennai.',
 'எங்கள் அடிப்படை அழகுக்கலை பாடம், விரைவாகவும் நம்பிக்கையுடனும் இத்துறையில் நுழைய விரும்பும் பெண்களுக்கான நிரூபிக்கப்பட்ட தொடக்கப் பாதை. மூன்று மாதங்களில் த்ரெடிங், வாக்ஸிங், ப்ளீச், அடிப்படை ஃபேஷியல், மானிக்யூர், பெடிக்யூர், தலை மசாஜ் மற்றும் சுகாதார நடைமுறைகளில் தேர்ச்சி பெறுவீர்கள். ஒவ்வொரு நாளும் சிறிய கோட்பாட்டுடன் நேரடி மாடல்களில் நீண்ட பயிற்சி இணையும். பத்து மாணவிகள் கொண்ட பேட்ச், ஆரம்ப கிட், அரசு அங்கீகார சான்றிதழ், இன்டர்ன்ஷிப் மற்றும் வேலைவாய்ப்பு வழிகாட்டுதலுடன் — அழகுக்கலையில் வருமானம் ஈட்ட விரைவான, பாதுகாப்பான வழி.',
 array['Salon hygiene, sterilisation & client safety','Eyebrow threading & shaping','Waxing techniques & skin prep','Bleach & detan procedures','Basic facials for all skin types','Manicure & pedicure','Head, neck & shoulder massage'],
 array['அழகு நிலைய சுகாதாரம் & கருவி கிருமி நீக்கம்','புருவ த்ரெடிங் & வடிவமைப்பு','வாக்ஸிங் நுட்பங்கள் & சருமம் தயாரிப்பு','ப்ளீச் & டீடான் முறைகள்','அனைத்து சரும வகைகளுக்கும் அடிப்படை ஃபேஷியல்','மானிக்யூர் & பெடிக்யூர்','தலை, கழுத்து & தோள் மசாஜ்'],
 'Women aged 16–45 across Tamil Nadu — absolute beginners who want a recognised qualification and a fast start in beauty.',
 'தமிழ்நாடு முழுவதும் 16–45 வயது பெண்கள் — அங்கீகரிக்கப்பட்ட தகுதியும் விரைவான தொடக்கமும் விரும்பும் புதியவர்கள்.',
 true,true,true,1,true),
('advanced-beautician','Advanced Beautician','மேம்பட்ட அழகுக்கலை','6 months',null,
 'Designed for women who want a serious career, the Advanced Beautician course expands every basic skill into specialist-level expertise across six months. You master advanced facials, derma cleanups, anti-tan and pigmentation treatments, party and engagement makeup, professional hair styling, nail art, and modern salon management including pricing, retention and inventory. Trainers stay one-to-one wherever it counts, exams run on live models, and graduates leave with a government-recognised advanced certificate, a portfolio of real client work, internship hours and placement support — the right course if you intend to manage or open your own salon within a year.',
 'தீவிர தொழில் வாழ்க்கையை விரும்பும் பெண்களுக்காக வடிவமைக்கப்பட்ட இந்த 6 மாத பாடம், ஒவ்வொரு அடிப்படை திறனையும் நிபுணத்துவ அளவிற்கு உயர்த்துகிறது. மேம்பட்ட ஃபேஷியல், டெர்மா க்ளீன்அப், டான் & பிக்மென்டேஷன் சிகிச்சைகள், பார்ட்டி மேக்கப், தொழில்முறை ஹேர் ஸ்டைலிங், நெயில் ஆர்ட் மற்றும் அழகு நிலைய நிர்வாகத்தில் தேர்ச்சி பெறுவீர்கள். 1:1 பயிற்சி, நேரடி மாடல் தேர்வுகள், அரசு அங்கீகார மேம்பட்ட சான்றிதழ், போர்ட்ஃபோலியோ, இன்டர்ன்ஷிப் மற்றும் வேலைவாய்ப்பு உதவி — ஓராண்டிற்குள் சொந்த அழகு நிலையம் தொடங்க விரும்புபவர்களுக்கான சரியான பாடம்.',
 array['Everything from Basic Beautician','Advanced facials (gold, fruit, oxygen, derma)','Pigmentation & anti-tan treatments','Party, engagement & reception makeup','Professional hair styling fundamentals','Nail art & extensions intro','Salon management, pricing & retention'],
 array['அடிப்படை அழகுக்கலை அனைத்தும்','மேம்பட்ட ஃபேஷியல்கள் (கோல்ட், ஃப்ரூட், ஆக்ஸிஜன், டெர்மா)','பிக்மென்டேஷன் & டான் சிகிச்சைகள்','பார்ட்டி, நிச்சயம் & வரவேற்பு மேக்கப்','தொழில்முறை ஹேர் ஸ்டைலிங் அடிப்படைகள்','நெயில் ஆர்ட் & எக்ஸ்டென்ஷன் அறிமுகம்','அழகு நிலைய நிர்வாகம் & விலையிடல்'],
 'Working beauticians and ambitious beginners who want to manage or open their own salon within a year.',
 'ஓராண்டிற்குள் சொந்த நிலையம் நடத்த விரும்பும் பணிபுரிபவர்கள் மற்றும் ஆர்வமுள்ள புதியவர்கள்.',
 true,true,true,2,true),
('diploma-cosmetology','Diploma in Cosmetology','காஸ்மெட்டாலஜி டிப்ளமோ','1 year',null,
 'The Diploma in Cosmetology is our flagship twelve-month programme for women who want a full, recognised qualification. The curriculum blends skin science, hair science, advanced makeup, nail technology, salon business, photoshoot styling and bridal work — taught in rotating modules with monthly live-model assessments. Class sizes stay small, you build a real client portfolio across the year, and you graduate with a government-recognised diploma plus structured internship and placement support. EMI options are available, kits are included, and former students of this course have gone on to open salons across Tamil Nadu and join leading brands.',
 'காஸ்மெட்டாலஜி டிப்ளமோ எங்களின் முதன்மை 12 மாத திட்டம் — முழுமையான, அங்கீகரிக்கப்பட்ட தகுதியை விரும்பும் பெண்களுக்காக. சரும அறிவியல், முடி அறிவியல், மேம்பட்ட மேக்கப், நெயில் டெக்னாலஜி, அழகு நிலைய வணிகம், ஃபோட்டோ ஷூட் ஸ்டைலிங் மற்றும் மணப்பெண் வேலைகள் — மாதாந்திர நேரடி மாடல் மதிப்பீடுகளுடன் சுழற்சி முறையில் கற்பிக்கப்படுகின்றன. சிறிய பேட்ச், ஓராண்டு போர்ட்ஃபோலியோ, அரசு அங்கீகார டிப்ளமோ, இன்டர்ன்ஷிப் & வேலைவாய்ப்பு உதவி, EMI வசதி மற்றும் கிட். இந்த பாடத்தின் முன்னாள் மாணவிகள் தமிழ்நாடு முழுவதும் அழகு நிலையங்களைத் தொடங்கியுள்ளனர்.',
 array['Skin anatomy & cosmetic science','Hair anatomy, cutting & colouring','Advanced makeup incl. HD/airbrush intro','Bridal makeup & saree draping','Nail technology & nail art','Salon business, branding & marketing','Final live-model board exam'],
 array['சரும அமைப்பு & ஒப்பனை அறிவியல்','முடி அமைப்பு, கட்டிங் & கலரிங்','மேம்பட்ட மேக்கப் (HD/ஏர்ப்ரஷ் அறிமுகம்)','மணப்பெண் மேக்கப் & சேலை கட்டுதல்','நெயில் டெக்னாலஜி & நெயில் ஆர்ட்','அழகு நிலைய வணிகம் & மார்க்கெட்டிங்','இறுதி நேரடி மாடல் தேர்வு'],
 'Women who want a complete, recognised qualification and a job-ready portfolio in salon, bridal or freelance work.',
 'அழகு நிலையம், மணப்பெண் அல்லது ஃப்ரீலான்ஸ் பணிக்கு தயாராக முழுமையான தகுதி விரும்பும் பெண்கள்.',
 true,true,true,3,true)
on conflict (slug) do nothing;

insert into public.courses
  (slug, name_en, name_ta, duration, price, summary_en, summary_ta, syllabus_en, syllabus_ta, who_for_en, who_for_ta, certificate, placement, emi, sort_order, published)
values
('hair-styling','Hair Styling','ஹேர் ஸ்டைலிங்','Flexible',null,
 'If hair is your passion, this dedicated Hair Styling course turns you into a confident hair specialist for salon, bridal and editorial work. You learn face-shape analysis, layered and blunt cutting, balayage and global colouring, smoothening fundamentals, blow-dry science, curling and bridal hair architecture including jadai, low buns and floral set-ups. Every technique is practised on real heads with one-to-one trainer correction, and the syllabus is updated each batch to match what brides and clients are asking for in Chennai. You graduate with a portfolio shoot and our government-recognised certificate.',
 'முடி உங்கள் ஆர்வமாக இருந்தால், இந்த ஹேர் ஸ்டைலிங் பாடம் உங்களை நம்பிக்கையான ஹேர் நிபுணராக மாற்றும். முக வடிவ பகுப்பாய்வு, லேயர் & ப்ளண்ட் கட்டிங், பாலியேஜ் & கிளோபல் கலர், ஸ்மூத்னிங், ப்ளோ-டிரை, கர்லிங் மற்றும் மணப்பெண் ஹேர் (ஜடை, லோ-பன், மலர் அலங்காரம்) ஆகியவற்றில் தேர்ச்சி பெறுவீர்கள். ஒவ்வொரு நுட்பமும் உண்மையான தலையில் 1:1 பயிற்சியுடன் கற்பிக்கப்படுகிறது. போர்ட்ஃபோலியோ ஷூட்டுடன் அரசு அங்கீகார சான்றிதழ் வழங்கப்படுகிறது.',
 array['Face shape analysis & consultation','Layered, blunt and trendy cuts','Global colour, highlights & balayage','Smoothening & care fundamentals','Blow-dry, curling & ironing','Bridal jadai, buns & floral hairstyles'],
 array['முக வடிவ பகுப்பாய்வு & ஆலோசனை','லேயர், ப்ளண்ட் & நவீன கட்கள்','கிளோபல் கலர், ஹைலைட்ஸ் & பாலியேஜ்','ஸ்மூத்னிங் & பராமரிப்பு','ப்ளோ-டிரை, கர்லிங் & ஐரனிங்','மணப்பெண் ஜடை, பன் & மலர் ஹேர்'],
 'Anyone passionate about hair who wants salon, bridal or editorial styling skills.',
 'அழகு நிலையம், மணப்பெண் அல்லது எடிட்டோரியல் ஹேர் திறன் விரும்பும் எவரும்.',
 true,true,true,4,true),
('makeup-artistry','Makeup Artistry','மேக்கப் ஆர்ட்டிஸ்ட்ரி','Flexible',null,
 'Makeup Artistry is built for the woman who wants to live behind the brush. Across this course you learn skin prep and colour theory, base building for Indian skin tones, contouring and highlighting, eye looks (smokey, cut-crease, soft glam), lip techniques, false-lash application and HD finishing. We practise on real faces every day, you build a digital portfolio shot in our studio area, and exit-level batches handle full party and engagement clients live. Graduation includes a government-recognised certificate, internship hours, and our placement network across Chennai studios and bridal teams.',
 'தூரிகையின் பின்னால் வாழ விரும்பும் பெண்களுக்காக வடிவமைக்கப்பட்டது. சருமம் தயாரிப்பு, நிற கோட்பாடு, இந்திய சருமத்திற்கான பேஸ் பில்டிங், கான்டூரிங் & ஹைலைட்டிங், கண் லுக்குகள் (ஸ்மோக்கி, கட்-கிரீஸ், சாஃப்ட் கிளாம்), உதடு நுட்பங்கள், ஃபால்ஸ் லேஷ் மற்றும் HD ஃபினிஷிங் கற்றுக்கொள்வீர்கள். ஒவ்வொரு நாளும் உண்மையான முகங்களில் பயிற்சி, டிஜிட்டல் போர்ட்ஃபோலியோ, மற்றும் இறுதி பேட்ச்களில் முழு பார்ட்டி & நிச்சய வாடிக்கையாளர்களை கையாள்வீர்கள். அரசு அங்கீகார சான்றிதழ் & சென்னை வேலைவாய்ப்பு வலையமைப்பு.',
 array['Skin prep & colour theory','Base building for Indian skin','Contour, highlight & blush','Eye looks: smokey, cut crease, soft glam','Lip artistry & lash application','HD makeup & airbrush intro'],
 array['சருமம் தயாரிப்பு & நிற கோட்பாடு','இந்திய சருமத்திற்கான பேஸ் பில்டிங்','கான்டூர், ஹைலைட் & ப்ளஷ்','கண் லுக்குகள்: ஸ்மோக்கி, கட்-கிரீஸ், கிளாம்','உதடு கலை & லேஷ் அப்ளிகேஷன்','HD மேக்கப் & ஏர்ப்ரஷ் அறிமுகம்'],
 'Aspiring makeup artists who want studio-quality skills and a portfolio.',
 'ஸ்டுடியோ தர திறன் & போர்ட்ஃபோலியோ விரும்பும் வளரும் மேக்கப் கலைஞர்கள்.',
 true,true,true,5,true),
('nail-technician','Nail Technician','நெயில் டெக்னீஷியன்','Flexible',null,
 'Nails are one of Chennai''s fastest-growing salon revenue streams, and this Nail Technician course makes you specialist-ready quickly. You master nail anatomy, hygiene and sterilisation, classic and spa manicure-pedicure, gel polish application, builder-gel overlays, acrylic and tip extensions, and trending nail art including French, ombre, marble, foil, encapsulated and 3D designs. Every technique is practised on real clients under supervision, and the course wraps with a portfolio shoot, a government-recognised certificate and a starter nail kit so you can begin earning the day you graduate.',
 'நெயில் சேவைகள் சென்னையில் வேகமாக வளரும் வருமான வழி. இந்த நெயில் டெக்னீஷியன் பாடம் உங்களை நிபுணராக மாற்றுகிறது. நெயில் அமைப்பு, சுகாதாரம், கிளாசிக் & ஸ்பா மானிக்யூர்-பெடிக்யூர், ஜெல் பாலிஷ், பில்டர் ஜெல், அக்ரிலிக் & டிப் எக்ஸ்டென்ஷன் மற்றும் ட்ரெண்டிங் நெயில் ஆர்ட் (பிரெஞ்ச், ஓம்பிரே, மார்பிள், ஃபாயில், 3D) பயிற்சி பெறுவீர்கள். உண்மையான வாடிக்கையாளர்களில் பயிற்சி, போர்ட்ஃபோலியோ ஷூட், அரசு அங்கீகார சான்றிதழ் & ஆரம்ப கிட்.',
 array['Nail anatomy, hygiene & sterilisation','Classic & spa manicure / pedicure','Gel polish & builder gel','Acrylic & tip extensions','Nail art: French, ombre, marble, foil','3D & encapsulated designs'],
 array['நெயில் அமைப்பு, சுகாதாரம் & கிருமி நீக்கம்','கிளாசிக் & ஸ்பா மானிக்யூர்/பெடிக்யூர்','ஜெல் பாலிஷ் & பில்டர் ஜெல்','அக்ரிலிக் & டிப் எக்ஸ்டென்ஷன்','நெயில் ஆர்ட்: பிரெஞ்ச், ஓம்பிரே, மார்பிள்','3D & என்காப்சுலேட்டட் டிசைன்கள்'],
 'Anyone who wants a specialist nail-tech career and a salon-ready portfolio.',
 'நிபுணத்துவ நெயில் டெக் தொழில் & போர்ட்ஃபோலியோ விரும்பும் எவரும்.',
 true,true,true,6,true),
('bridal-makeup','Bridal Makeup','மணப்பெண் மேக்கப்','Flexible',null,
 'Bridal is the highest-paying segment in Indian beauty, and this course is built specifically to make you a confident bridal artist. You master long-wear base building, traditional Tamil bridal looks, modern HD and airbrush bridal makeup, draping fundamentals, jadai-with-flowers, jewellery setting and the all-important on-the-day timeline. The course pairs you with real bridal clients during exit batches, captures every look in a styled photoshoot for your portfolio, and ends with a government-recognised certificate plus introductions to bridal teams across Chennai for placements and freelance leads.',
 'இந்திய அழகுக் கலையில் அதிக வருமானம் தரும் பிரிவு மணப்பெண் வேலை. நீண்ட நேரம் தாங்கும் பேஸ், பாரம்பரிய தமிழ் மணப்பெண் லுக், நவீன HD & ஏர்ப்ரஷ் மணப்பெண் மேக்கப், சேலை அலங்காரம், மலர் ஜடை, நகை அமைப்பு மற்றும் நாள்-நேர திட்டம் ஆகியவற்றில் தேர்ச்சி பெறுவீர்கள். இறுதி பேட்ச்களில் உண்மையான மணப்பெண் வாடிக்கையாளர்களுடன் பணியாற்றி, ஸ்டைல்டு ஃபோட்டோஷூட் போர்ட்ஃபோலியோ உருவாக்கி, அரசு அங்கீகார சான்றிதழ் & சென்னை மணப்பெண் குழுக்களுக்கான அறிமுகம் பெறுவீர்கள்.',
 array['Long-wear bridal base building','Traditional Tamil bridal makeup','HD & airbrush bridal makeup','Saree draping fundamentals','Jadai-with-flowers & jewellery setting','On-the-day timeline & client management'],
 array['நீண்ட நேர மணப்பெண் பேஸ்','பாரம்பரிய தமிழ் மணப்பெண் மேக்கப்','HD & ஏர்ப்ரஷ் மணப்பெண் மேக்கப்','சேலை அலங்காரம் அடிப்படைகள்','மலர் ஜடை & நகை அமைப்பு','நாள்-நேர திட்டம் & வாடிக்கையாளர் மேலாண்மை'],
 'Makeup lovers who want to enter the high-paying bridal segment.',
 'அதிக வருமானம் தரும் மணப்பெண் பிரிவில் நுழைய விரும்புபவர்கள்.',
 true,true,true,7,true),
('mehendi-henna','Mehendi / Henna','மருதாணி / மெஹந்தி','Flexible',null,
 'Mehendi is one of the easiest, highest-margin skills a woman can pick up — a single bride can earn what a week of salon work earns. This course takes you from holding the cone correctly to designing full bridal hands and feet. You learn paste preparation, line control, fillers, peacock and floral motifs, Arabic style, modern minimal style, full Indian bridal hands and feet, jewellery-style mehendi, and pricing strategy for festivals and weddings. The course includes practice sheets, hand models in later weeks, and our government-recognised certificate.',
 'மருதாணி கலை — ஒரு பெண் கற்கக்கூடிய எளிய, அதிக லாபம் தரும் திறன்களில் ஒன்று. கூம்பு பிடிப்பதில் இருந்து முழு மணப்பெண் கை-கால் வடிவமைக்கும் வரை. பேஸ்ட் தயாரிப்பு, லைன் கட்டுப்பாடு, ஃபில்லர்கள், மயில் & மலர் வடிவங்கள், அரேபிய ஸ்டைல், நவீன மினிமல் ஸ்டைல், முழு இந்திய மணப்பெண் கை & கால், நகை-ஸ்டைல் மருதாணி மற்றும் விலையிடல் உத்திகள். பயிற்சி தாள்கள், கை மாடல்கள் & அரசு அங்கீகார சான்றிதழ்.',
 array['Paste prep & cone control','Line work & fillers','Peacock, floral & paisley motifs','Arabic & modern minimal styles','Full Indian bridal hands & feet','Pricing & client booking'],
 array['பேஸ்ட் தயாரிப்பு & கூம்பு கட்டுப்பாடு','லைன் வேலை & ஃபில்லர்கள்','மயில், மலர் & பைஸ்லி வடிவங்கள்','அரேபிய & நவீன மினிமல் ஸ்டைல்','முழு இந்திய மணப்பெண் கை & கால்','விலையிடல் & புக்கிங்'],
 'Anyone who wants reliable festival- and wedding-season income from mehendi.',
 'பண்டிகை & திருமண சீசன் வருமானம் விரும்புபவர்கள்.',
 true,true,true,8,true),
('skin-care','Skin Care','சரும பராமரிப்பு','Flexible',null,
 'Modern clients want results, not just relaxation, and this Skin Care course teaches you to deliver them. You study skin anatomy, common Indian-skin concerns (tan, pigmentation, acne, dehydration, ageing), how to read a face and consult clearly, and how to design facials and treatments around real outcomes. Practical modules cover deep cleansing, exfoliation, serum and mask layering, oxygen and gold facials, derma cleanups, anti-tan and brightening protocols, and home-care prescriptions clients will actually follow. You graduate with a portfolio of real before-and-after work and our government-recognised certificate.',
 'நவீன வாடிக்கையாளர்கள் முடிவுகளை எதிர்பார்க்கிறார்கள் — இந்த சரும பராமரிப்பு பாடம் அதைத் தர கற்றுக்கொடுக்கிறது. சரும அமைப்பு, இந்திய சருமப் பிரச்சினைகள் (டான், பிக்மென்டேஷன், முகப்பரு, வறட்சி, வயது), முகத்தைப் படித்து ஆலோசனை வழங்குவது, உண்மையான முடிவுகளை மையமாகக் கொண்ட ஃபேஷியல் & சிகிச்சைகள். ஆழமான சுத்தம், எக்ஸ்ஃபோலியேஷன், செரம் & மாஸ்க், ஆக்ஸிஜன் & கோல்ட் ஃபேஷியல், டெர்மா க்ளீன்அப், டான் & பிரகாச சிகிச்சைகள் மற்றும் வீட்டு பராமரிப்பு பரிந்துரைகள். உண்மையான முன்-பின் போர்ட்ஃபோலியோவுடன் அரசு அங்கீகார சான்றிதழ்.',
 array['Skin anatomy & concern analysis','Cleansing, exfoliation & masking','Serum, ampoule & mask layering','Oxygen, gold & fruit facials','Derma cleanups & extractions','Anti-tan, brightening & anti-ageing'],
 array['சரும அமைப்பு & பிரச்சினை பகுப்பாய்வு','சுத்தம், எக்ஸ்ஃபோலியேஷன் & மாஸ்கிங்','செரம், ஆம்ப்யூல் & மாஸ்க்','ஆக்ஸிஜன், கோல்ட் & ஃப்ரூட் ஃபேஷியல்','டெர்மா க்ளீன்அப் & எக்ஸ்ட்ராக்ஷன்','டான், பிரகாச & வயது எதிர்ப்பு'],
 'Those who want to become result-driven skin specialists.',
 'முடிவு சார்ந்த சரும நிபுணராக மாற விரும்புபவர்கள்.',
 true,true,true,9,true),
('saree-draping','Saree Draping','சேலை கட்டுதல்','Flexible',null,
 'A great drape can change a face, and a great draper is booked solid every wedding season. This Saree Draping course walks you through 20+ styles spanning Tamil traditional madisar, Nivi, butterfly, lehenga-style, mermaid, dhoti, modern bridal and reception drapes. You learn pleat counting, pinning that holds for twelve hours, accessory placement, ironing and emergency fixes, and on-set draping for photoshoots. We use a wide range of fabric weights so you graduate confident with both silk and lighter fabrics, and the course closes with a portfolio shoot and our certificate.',
 'ஒரு சிறந்த சேலை அலங்காரம் முகத்தையே மாற்றும், திறமையான ட்ரேப்பருக்கு திருமண சீசனில் வேலை குறையாது. இந்த பாடம் 20+ ஸ்டைல்களை கற்றுக்கொடுக்கிறது — தமிழ் பாரம்பரிய மடிசார், நிவி, பட்டர்ஃப்ளை, லெஹங்கா-ஸ்டைல், மெர்மெய்ட், தோத்தி, நவீன மணப்பெண் & வரவேற்பு. ப்ளீட் எண்ணுதல், 12 மணி நேரம் தாங்கும் பின்னிங், அக்செசரி அமைப்பு, இஸ்திரி & அவசர சரிசெய்தல், ஃபோட்டோஷூட் அலங்காரம். பல்வேறு துணி எடைகளில் பயிற்சி, போர்ட்ஃபோலியோ ஷூட் & சான்றிதழ்.',
 array['Pleat counting & pinning','Tamil traditional madisar','Nivi, butterfly & mermaid drapes','Lehenga-style & dhoti drapes','Modern bridal & reception drapes','Photoshoot draping & accessories'],
 array['ப்ளீட் எண்ணுதல் & பின்னிங்','தமிழ் பாரம்பரிய மடிசார்','நிவி, பட்டர்ஃப்ளை & மெர்மெய்ட்','லெஹங்கா-ஸ்டைல் & தோத்தி','நவீன மணப்பெண் & வரவேற்பு','ஃபோட்டோஷூட் அலங்காரம் & அக்செசரி'],
 'Anyone who wants professional draping skills and wedding-season income.',
 'தொழில்முறை சேலை அலங்கார திறன் & திருமண சீசன் வருமானம் விரும்புபவர்கள்.',
 true,true,true,10,true),
('eyelash-extension','Eyelash Extension','ஐலாஷ் எக்ஸ்டென்ஷன்','Flexible',null,
 'Lash extensions are the fastest-growing premium service in Indian salons because clients pay well and rebook every three weeks. This course makes you a confident certified lash artist. You learn eye anatomy and contraindications, hygiene and patch testing, mapping for different eye shapes, isolation, classic one-to-one application, hybrid mixing, volume fans handmade and pre-made, retouch and removal, and aftercare. We practise on mannequin pads first, then real models. You exit with a portfolio, a starter lash kit and a government-recognised certificate, ready to add lashes to your menu or freelance immediately.',
 'ஐலாஷ் எக்ஸ்டென்ஷன் இந்திய அழகு நிலையங்களில் வேகமாக வளரும் ப்ரீமியம் சேவை — வாடிக்கையாளர்கள் 3 வாரத்திற்கு ஒருமுறை மீண்டும் வருகிறார்கள். இந்த பாடம் உங்களை சான்றளிக்கப்பட்ட லாஷ் கலைஞராக மாற்றும். கண் அமைப்பு & எதிர்-சுட்டிகள், சுகாதாரம் & பேட்ச் டெஸ்ட், மேப்பிங், ஐசோலேஷன், கிளாசிக் 1:1, ஹைபிரிட், வால்யூம் ஃபேன், ரீடச் & நீக்கம், ஆஃப்டர்கேர். மேனிகின் பேட்களில் முதலில், பின் உண்மையான மாடல்களில் பயிற்சி. போர்ட்ஃபோலியோ, ஆரம்ப கிட் & அரசு அங்கீகார சான்றிதழ்.',
 array['Eye anatomy & contraindications','Hygiene, patch test & client prep','Mapping for eye shapes','Isolation & classic 1:1 application','Hybrid mixing & volume fans','Retouch, removal & aftercare'],
 array['கண் அமைப்பு & எதிர்-சுட்டிகள்','சுகாதாரம், பேட்ச் டெஸ்ட் & தயாரிப்பு','கண் வடிவங்களுக்கான மேப்பிங்','ஐசோலேஷன் & கிளாசிக் 1:1','ஹைபிரிட் மிக்ஸ் & வால்யூம் ஃபேன்','ரீடச், நீக்கம் & ஆஃப்டர்கேர்'],
 'Beauty professionals who want to add a premium lash service.',
 'ப்ரீமியம் லாஷ் சேவையைச் சேர்க்க விரும்பும் அழகுத் தொழில் வல்லுநர்கள்.',
 true,true,true,11,true)
